import type { GpsCoordinates } from './geolocation';

const loadImageFromFile = (file: File): Promise<HTMLImageElement> =>
  new Promise((resolve, reject) => {
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      URL.revokeObjectURL(url);
      resolve(img);
    };
    img.onerror = () => {
      URL.revokeObjectURL(url);
      reject(new Error('Could not load image for GPS embedding.'));
    };
    img.src = url;
  });

const canvasToBlob = (canvas: HTMLCanvasElement, type: string, quality: number): Promise<Blob> =>
  new Promise((resolve, reject) => {
    canvas.toBlob(
      (blob) => {
        if (!blob) {
          reject(new Error('Failed to encode geotagged image.'));
          return;
        }
        resolve(blob);
      },
      type,
      quality
    );
  });

export type GpsEmbedOptions = {
  coords: GpsCoordinates;
  purposeLabel: string;
  capturedAtLabel?: string;
};

const MAX_CANVAS_EDGE = 4096;

/**
 * Burns GPS coordinates into the image pixels (bottom stamp) so lat/long travel with the file.
 * Falls back to the original file when the browser cannot decode/draw the image (e.g. HEIC).
 * GPS metadata is still sent with the upload form fields in that case.
 */
export async function embedGpsCoordinatesInImage(
  file: File,
  options: GpsEmbedOptions
): Promise<File> {
  try {
    const { coords, purposeLabel } = options;
    const img = await loadImageFromFile(file);
    const naturalWidth = img.naturalWidth || img.width;
    const naturalHeight = img.naturalHeight || img.height;
    if (!naturalWidth || !naturalHeight) {
      return file;
    }

    const scale = Math.min(1, MAX_CANVAS_EDGE / Math.max(naturalWidth, naturalHeight));
    const canvas = document.createElement('canvas');
    canvas.width = Math.max(1, Math.round(naturalWidth * scale));
    canvas.height = Math.max(1, Math.round(naturalHeight * scale));
    const ctx = canvas.getContext('2d');
    if (!ctx) {
      return file;
    }

    ctx.drawImage(img, 0, 0, canvas.width, canvas.height);

    const capturedAt = options.capturedAtLabel
      || (coords.capturedAt ? new Date(coords.capturedAt).toLocaleString() : new Date().toLocaleString());
    const accuracyLabel = coords.accuracyMeters != null
      ? `±${Math.round(coords.accuracyMeters)} m`
      : 'n/a';

    const lines = [
      purposeLabel,
      `GPS ${coords.latitude.toFixed(6)}, ${coords.longitude.toFixed(6)}`,
      `Accuracy ${accuracyLabel} · ${capturedAt}`,
    ];

    const padding = Math.max(12, Math.round(canvas.width * 0.012));
    const lineHeight = Math.max(18, Math.round(canvas.width * 0.022));
    const barHeight = padding * 2 + lineHeight * lines.length;
    const fontSize = Math.max(14, Math.round(canvas.width * 0.018));

    ctx.fillStyle = 'rgba(0, 0, 0, 0.72)';
    ctx.fillRect(0, canvas.height - barHeight, canvas.width, barHeight);

    ctx.fillStyle = '#ffffff';
    ctx.font = `600 ${fontSize}px system-ui, -apple-system, Segoe UI, sans-serif`;
    ctx.textBaseline = 'top';
    lines.forEach((line, index) => {
      ctx.fillText(line, padding, canvas.height - barHeight + padding + index * lineHeight);
    });

    const outputType = file.type === 'image/png' ? 'image/png' : 'image/jpeg';
    const blob = await canvasToBlob(canvas, outputType, 0.92);
    const baseName = (file.name || 'geotagged-photo').replace(/\.[^.]+$/, '');
    const extension = outputType === 'image/png' ? '.png' : '.jpg';

    return new File([blob], `${baseName}-geotagged${extension}`, {
      type: outputType,
      lastModified: Date.now(),
    });
  } catch {
    // Keep upload path alive: form GPS fields remain the source of truth.
    return file;
  }
}
