import React, { useRef } from 'react';
import { Box, Button } from '@mui/material';
import { Link as RouterLink, Navigate, useLocation } from 'react-router-dom';
import { OPERATIONS_REVIEW_PATH, myCompanyNavPages, operationsPageFromPath } from '../constants/workspacePages';
import ManufacturingWorkflowPlanner from './ManufacturingWorkflowPlanner';
import MsmeReportingFacilityEditor, { type FacilitySaveHandle } from './MsmeReportingFacilityEditor';
import { useMsmeProfileQuery } from '../hooks/queries/useMsmeWorkspaceQueries';
import WorkspacePageHeader from './shared/WorkspacePageHeader';
import MyCompanyRequiredNotice from './MyCompanyRequiredNotice';

const OperationsPage: React.FC = () => {
  const location = useLocation();
  const operationsPage = operationsPageFromPath(location.pathname);
  const profileQuery = useMsmeProfileQuery();
  const energySaveRef = useRef<FacilitySaveHandle | null>(null);

  const profile = (profileQuery.data as { data?: Record<string, unknown> } | undefined)?.data
    ?? (profileQuery.data as Record<string, unknown> | undefined)
    ?? null;

  const companyPages = myCompanyNavPages();
  const pageIndex = companyPages.findIndex((page) => page.path === location.pathname);
  const nextPage = pageIndex >= 0 ? companyPages[pageIndex + 1] : undefined;

  if (location.pathname === OPERATIONS_REVIEW_PATH) {
    return <Navigate to="/msme-profile/boundaries" replace />;
  }

  if (!operationsPage) {
    return <Navigate to="/operations" replace />;
  }

  return (
    <Box>
      <WorkspacePageHeader
        title={operationsPage.navLabel}
        description={operationsPage.id === 'picture'
          ? 'Energy source, electricity supplier, fuels, and monthly meters.'
          : operationsPage.id === 'units'
            ? 'Name each unit and the products it makes. GPS and capacity are optional.'
            : operationsPage.id === 'scope1'
              ? 'Choose the boilers, vehicles, process gas, or leaks you have, then save.'
              : 'Keep the value-chain activities you use, and note anything you leave out.'}
      />

      {profile ? (
        <MyCompanyRequiredNotice
          profile={profile}
          pageId={operationsPage.id === 'picture' ? 'energy' : operationsPage.id}
          saving={profileQuery.isFetching && !profileQuery.isLoading}
        />
      ) : null}

      {profile && operationsPage.id === 'picture' ? (
        <MsmeReportingFacilityEditor
          section="energy"
          profile={profile}
          saveHandleRef={energySaveRef}
          onSaved={async () => {
            await profileQuery.refetch();
          }}
        />
      ) : null}

      <ManufacturingWorkflowPlanner
        isEmbeddedInOperationsPage
        operationsView={operationsPage.id}
        saveEnergyDetails={operationsPage.id === 'picture'
          ? () => energySaveRef.current?.save() ?? Promise.resolve(false)
          : undefined}
      />

      {profile && operationsPage.id === 'units' ? (
        <Box sx={{ mt: 2 }}>
          <MsmeReportingFacilityEditor
            section="site"
            profile={profile}
            onSaved={() => { void profileQuery.refetch(); }}
          />
        </Box>
      ) : null}

      {nextPage ? (
        <Box sx={{ mt: 2 }}>
          <Button component={RouterLink} to={nextPage.path} variant="text">
            {nextPage.navLabel}
          </Button>
        </Box>
      ) : null}
    </Box>
  );
};

export default OperationsPage;
